import json
import statistics

def detect_yoy_anomalies(json_data: str) -> dict:
    try:
        if not isinstance(json_data, str):
            return {"status": "ERROR", "error": "Input must be a JSON string"}

        try:
            data = json.loads(json_data)
        except json.JSONDecodeError as e:
            return {"status": "ERROR", "error": f"Invalid JSON format: {str(e)}"}

        if not isinstance(data, list):
            return {"status": "ERROR", "error": "JSON input must be a list of records"}

        if len(data) < 2:
            return {"status": "ERROR", "error": "At least two records are required to calculate YoY change"}

        records = []
        for i, item in enumerate(data):
            if not isinstance(item, dict):
                return {"status": "ERROR", "error": f"Record at index {i} is not a valid dictionary"}
            if "year" not in item or "total" not in item:
                return {"status": "ERROR", "error": f"Record at index {i} is missing 'year' or 'total'"}

            try:
                year = int(item["year"])
                total = float(item["total"])
            except (ValueError, TypeError):
                return {"status": "ERROR", "error": f"Invalid numerical values for 'year' or 'total' at index {i}"}

            records.append({"year": year, "total": total})

        records.sort(key=lambda x: x["year"])

        yoy_records = []
        for i in range(1, len(records)):
            prev = records[i - 1]
            curr = records[i]

            prev_total = prev["total"]
            curr_total = curr["total"]

            if prev_total == 0:
                pct_change = 0.0
            else:
                pct_change = ((curr_total - prev_total) / abs(prev_total)) * 100.0

            yoy_records.append({
                "year": curr["year"],
                "pct_change": pct_change
            })

        changes = [r["pct_change"] for r in yoy_records]
        mean_change = statistics.mean(changes)
        stdev_change = statistics.stdev(changes) if len(changes) > 1 else 0.0

        results = []
        for r in yoy_records:
            year = r["year"]
            change = r["pct_change"]
            deviation = abs(change - mean_change)
            is_anomaly = deviation > stdev_change if stdev_change > 0 else False

            results.append({
                "year": year,
                "yoy_pct_change": round(change, 2),
                "is_anomaly": is_anomaly,
                "deviation_from_mean": round(deviation, 2)
            })

        return {
            "status": "SUCCESS",
            "summary": {
                "mean_yoy_change_pct": round(mean_change, 2),
                "stdev_yoy_change_pct": round(stdev_change, 2),
                "upper_threshold_pct": round(mean_change + stdev_change, 2),
                "lower_threshold_pct": round(mean_change - stdev_change, 2)
            },
            "yearly_analysis": results
        }
    except Exception as e:
        return {"status": "ERROR", "error": str(e)}
